// Lire la ligne compteur renvoyée par "Get row(s)"
const row = $input.first().json;

// Fenêtre horaire courante, ex. "2026-09-14-08" (heure UTC)
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const windowKey = `${now.getUTCFullYear()}-${pad(now.getUTCMonth() + 1)}-${pad(now.getUTCDate())}-${pad(now.getUTCHours())}`;

// Nouvelle heure => on repart à 1 ; même heure => on incrémente
let count;
if (row.window !== windowKey) {
  count = 1;
} else {
  count = (Number(row.count) || 0) + 1;
}

const THRESHOLD = 100; // messages max par heure, tous visiteurs confondus
const over = count > THRESHOLD;

return [{ json: { id: row.id, key: 'global', window: windowKey, count, over } }];
